// Pi's session format and retry state stay in this adapter so the core can serve other agents.

import { chmod, mkdir, stat } from "node:fs/promises";
import { dirname } from "node:path";
import { ApplicationFailure } from "@temporalio/activity";
import {
  createAgentSession,
  findDanglingToolCalls,
  ModelRuntime,
  SessionManager,
  unknownToolCallOutcome,
  type AgentSession as PiSession,
  type TurnToolCallOutcome,
} from "@earendil-works/pi-coding-agent";
import type { Agent, AgentSession, AgentState, ToolCallRef } from "../core/agent.js";
import type { Spend } from "../core/protocol.js";
import { textOf } from "./messages.js";

export interface PiOptions {
  // Where the agent's tools run. The embedded Worker points this at the pi session's own cwd.
  readonly projectDir: string;
  readonly provider?: string;
  // Matched as a substring of the model id, so "mini" picks the first mini the provider offers.
  readonly modelHint?: string;
  // Only needed when the key is not already in Pi's auth store.
  readonly apiKey?: string;
}

/** For checks: open a fake Pi session instead of a real one. */
export interface PiDependencies {
  readonly openSession?: (file: string, guard?: () => void) => Promise<PiSession>;
}

// A zero-width marker with the prompt id, so an Activity that runs again can tell whether this
// prompt was already recorded.
const marker = (promptId: string) => `​[pi-temporal:${promptId}]`;

type Msg = { role?: string; content?: unknown; toolCallId?: string };
type Block = { type?: string; id?: string };
type Entry = { type: string; customType?: string; data?: unknown; message?: unknown };
type Record = {
  getBranch(): Entry[];
  appendCustomEntry(customType: string, data: unknown): string;
};

const blocksOf = (content: unknown) => (Array.isArray(content) ? (content as Block[]) : []);
const latestResponse = (messages: Msg[]) =>
  [...messages].reverse().find((m) => m.role === "assistant");

// Optional, because the checks' fake sessions keep no record. A real session always has one.
const recordOf = (session: PiSession) =>
  (session as unknown as { sessionManager?: Record }).sessionManager;

const latestEntryOf = (
  record: Record | undefined,
  type: string,
  skip?: (data: unknown) => boolean,
) => {
  const branch = record?.getBranch() ?? [];
  for (let i = branch.length - 1; i >= 0; i--) {
    const entry = branch[i];
    if (entry.type !== "custom" || entry.customType !== type) continue;
    if (skip?.(entry.data)) continue;
    return entry.data;
  }
  return undefined;
};

/** Whether this turn's prompt is in the session file. A compaction can summarize the prompt out
 * of the context, but the branch keeps every raw message entry. */
const promptRecorded = (session: PiSession, promptId: string): boolean => {
  const record = recordOf(session);
  const messages =
    typeof record?.getBranch === "function"
      ? record
          .getBranch()
          .flatMap((entry) => (entry.type === "message" ? [entry.message as Msg] : []))
      : // Fake sessions in checks have no record. Their context is the whole transcript.
        (session.state.messages as Msg[]);
  return messages.some((m) => textOf(m.content).includes(marker(promptId)));
};

// Pi's retry count and its one compact-and-retry, carried by the Workflow between steps.
interface PiState {
  readonly retryAttempt?: number;
  readonly overflowRecoveryAttempted?: boolean;
}

function wrap(session: PiSession): AgentSession {
  const messages = () => session.state.messages as Msg[];
  return {
    prepareStep: () => session.prepareStep(),
    hasPrompt: (promptId) => promptRecorded(session, promptId),
    recordPrompt: (promptId, text) => session.recordPrompt(`${text}${marker(promptId)}`),
    // A stop aborts the call like a user stop, so Pi records an aborted response and the turn
    // ends as stopped. A unit already stopped asks the model nothing, and isn't billed.
    async modelCall(signal) {
      const outcome = await session.modelCall({ signal });
      return {
        toolCalls: outcome.toolCalls.map((call) => ({ id: call.id, name: call.name })),
        sequential: outcome.sequential,
        ended: outcome.ended,
      };
    },
    runToolCall: (callId, signal) => session.runToolCall(callId, { signal }),
    async sealStep(outcomes, { expectCalls, agentState, postRun, signal }) {
      const state = (agentState ?? {}) as PiState;
      const sealed = await session.sealStep(outcomes as TurnToolCallOutcome[], {
        expectCalls,
        retryAttempt: state.retryAttempt ?? 0,
        overflowRecoveryAttempted: state.overflowRecoveryAttempted,
        postRun,
        signal,
      });
      const next: PiState = {
        retryAttempt: sealed.retryAttempt,
        overflowRecoveryAttempted: sealed.overflowRecoveryAttempted,
      };
      return { done: sealed.done, agentState: next as AgentState };
    },
    waitForIdle: () => session.waitForIdle(),
    dispose: () => session.dispose(),

    // Only results after the latest response. Providers may reuse call ids across responses.
    answered(callId) {
      const all = messages();
      const opened = all.lastIndexOf(latestResponse(all) as Msg);
      return all.slice(opened + 1).some((m) => m.role === "toolResult" && m.toolCallId === callId);
    },
    asked: (callId) =>
      blocksOf(latestResponse(messages())?.content).some(
        (b) => b.type === "toolCall" && b.id === callId,
      ),
    unanswered: () =>
      findDanglingToolCalls(
        messages() as unknown as Parameters<typeof findDanglingToolCalls>[0],
      ).map((call) => call.id),
    endsWithResponse: () => messages().at(-1)?.role === "assistant",
    // The latest response only, even if empty. Looking further back would return an earlier
    // turn's answer.
    lastAnswer: () => textOf(latestResponse(messages())?.content),
    spend(): Spend | undefined {
      // Session-wide billing, compacted history included. Undefined for fake sessions in checks.
      type Stats = { tokens?: { total?: number }; cost?: number };
      const stats = (session as { getSessionStats?: () => Stats }).getSessionStats;
      if (typeof stats !== "function") return undefined;
      try {
        const now = stats.call(session);
        return { tokens: now.tokens?.total ?? 0, cost: now.cost ?? 0 };
      } catch {
        return undefined;
      }
    },
    latestEntry: (type, skip) => latestEntryOf(recordOf(session), type, skip),
    appendEntry: (type, data) => void recordOf(session)?.appendCustomEntry(type, data),
  };
}

/**
 * The session directory, owner only. The session holds the conversation, tool output included.
 * `mkdir` sets the mode only on a directory it creates, so one made before this rule is tightened
 * too. Only one this user owns. A directory shared on purpose is the operator's to manage.
 */
async function privateDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true, mode: 0o700 });
  const info = await stat(dir);
  if (info.uid === process.getuid?.() && (info.mode & 0o077) !== 0) await chmod(dir, 0o700);
}

export function piAgent(opts: PiOptions, dependencies: PiDependencies = {}): Agent {
  const provider = opts.provider ?? "openai";

  async function openSession(sessionFile: string, guard: () => void): Promise<PiSession> {
    if (dependencies.openSession) return dependencies.openSession(sessionFile, guard);
    await privateDir(dirname(sessionFile));
    const sessionManager = SessionManager.open(sessionFile);
    sessionManager.setWriteGuard(guard);

    // A bad key or provider fails the same way on every attempt, so don't retry it.
    const modelRuntime = await ModelRuntime.create().catch((err: unknown) => {
      throw ApplicationFailure.nonRetryable(`could not set up the model runtime: ${String(err)}`);
    });
    const available = await (async () => {
      if (opts.apiKey) await modelRuntime.setRuntimeApiKey(provider, opts.apiKey);
      return await modelRuntime.getAvailable(provider);
    })().catch((err: unknown) => {
      throw ApplicationFailure.nonRetryable(`could not set up ${provider}: ${String(err)}`);
    });
    // Default to the provider's small, cheap model.
    const hint = opts.modelHint ?? (provider === "anthropic" ? "haiku" : "mini");
    const model = available.find((m) => m.id.includes(hint)) ?? available[0];
    if (!model) {
      throw ApplicationFailure.nonRetryable(
        `no ${provider} model available; check the key and provider support`,
      );
    }

    const { session } = await createAgentSession({
      sessionManager,
      modelRuntime,
      model,
      cwd: opts.projectDir,
    });
    return session;
  }

  return {
    open: async (sessionFile, guard) => wrap(await openSession(sessionFile, guard)),
    async openRecord(sessionFile, guard) {
      // A fake session in a check stands in for the record too.
      const record = dependencies.openSession
        ? recordOf(await dependencies.openSession(sessionFile, guard))
        : await (async () => {
            await privateDir(dirname(sessionFile));
            const manager = SessionManager.open(sessionFile);
            manager.setWriteGuard(guard);
            return manager as unknown as Record;
          })();
      if (!record) return undefined;
      return {
        latestEntry: (type, skip) => latestEntryOf(record, type, skip),
        appendEntry: (type, data) => void record.appendCustomEntry(type, data),
      };
    },
    unknownOutcome: (call: ToolCallRef) => unknownToolCallOutcome(call),
    notRunOutcome(call: ToolCallRef) {
      const outcome = unknownToolCallOutcome(call);
      outcome.message.content = [
        { type: "text", text: "This tool call did not run. The turn stopped before it started." },
      ];
      return outcome;
    },
  };
}

// A whole `Agent` with no model and no Pi: its "model" asks for one `echo` tool call with the
// prompt's text, then answers with what the tool gave back. The session is a JSONL file of this
// file's own entries. Each rule a comment cites is under "What must hold" in docs/adapting.md.

import { appendFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";
import { ApplicationFailure } from "@temporalio/common";
import type {
  Agent,
  AgentSession,
  ModelCall,
  ToolCallRef,
} from "../../src/core/agent.js";

type Call = { id: string; name: string; text: string };
const outcomeStatuses = ["ok", "unknown", "not-run", "failed"] as const;
type Outcome = { callId: string; status: (typeof outcomeStatuses)[number]; text: string };
type Prompt = { kind: "prompt"; promptId: string; text: string };
type Response = {
  kind: "response";
  text: string;
  calls: Call[];
  tokens: number;
  aborted?: boolean;
};
type Result = { kind: "result" } & Outcome;
// The core's bookkeeping. Not part of the conversation.
type Note = { kind: "note"; type: string; data: unknown };
type Entry = Prompt | Response | Result | Note;

/** The echo tool. A check can pass a slow one, to stop a Worker while it runs. */
export type EchoTool = (text: string, signal?: AbortSignal) => Promise<string>;

export interface EchoOptions {
  readonly tool?: EchoTool;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isEntry(value: unknown): value is Entry {
  if (!isObject(value)) return false;
  switch (value.kind) {
    case "prompt":
      return typeof value.promptId === "string" && typeof value.text === "string";
    case "response":
      return typeof value.text === "string" && typeof value.tokens === "number" &&
        Array.isArray(value.calls) && value.calls.every((call: unknown) =>
          isObject(call) && typeof call.id === "string" && typeof call.name === "string" &&
          typeof call.text === "string") &&
        (value.aborted === undefined || typeof value.aborted === "boolean");
    case "result":
      return typeof value.callId === "string" && typeof value.text === "string" &&
        (outcomeStatuses as readonly unknown[]).includes(value.status);
    case "note":
      // data is deliberately unknown; JSON omits it when appendEntry receives undefined.
      return typeof value.type === "string";
    default:
      return false;
  }
}

// A broken file stays broken, so a retry would burn every attempt on the same error.
const notAnEntry = (file: string, verb: "read" | "written", line: string) =>
  ApplicationFailure.nonRetryable(
    `the session ${file} can't be ${verb}: not a session entry: ${line.slice(0, 80)}`,
  );

/** The line `entry` appends, and the entry a later read takes from it. */
function encode(file: string, entry: unknown): { line: string; entry: Entry } {
  let line: string | undefined;
  try {
    line = JSON.stringify(entry);
  } catch {
    // A BigInt or a cycle has no line to write.
  }
  // Checked as read back, not as given. JSON can change a value on the way, as NaN to null.
  const written: unknown = line === undefined ? undefined : JSON.parse(line);
  if (line === undefined || !isEntry(written)) {
    throw notAnEntry(file, "written", line ?? "[unserializable entry]");
  }
  return { line, entry: written };
}

function load(file: string): Entry[] {
  if (!existsSync(file)) return [];
  const text = readFileSync(file, "utf8");
  const entries: Entry[] = [];
  for (const line of text.split("\n")) {
    if (!line) continue;
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      // A cut line, now or from an earlier crash. Every entry is an object, and a cut object never
      // parses, so skipping it loses no whole entry.
      continue;
    }
    // A line that parses but isn't an entry is a broken file, not a crash.
    if (!isEntry(parsed)) throw notAnEntry(file, "read", line);
    entries.push(parsed);
  }
  return entries;
}

/** One file's entries, and the only way to add to them: through the guard. */
function journal(file: string, guard: () => void) {
  const entries = load(file);
  const append = (...batch: Entry[]) => {
    if (batch.length === 0) return;
    // Every append calls the guard before writing, and stops if it throws. That's the fence. It
    // goes before the check below, so a superseded writer reports the fence, not its entry.
    guard();
    // Runtime callers can bypass TypeScript. Never write an entry load() would reject, and check
    // the whole batch first, so a bad entry can't leave half of it written.
    const encoded = batch.map((entry) => encode(file, entry));
    for (const [i, { line, entry }] of encoded.entries()) {
      if (i > 0) guard();
      // Only appends, never a rewrite. The fence lets a superseded writer through for one write
      // after its guard, and an append can't erase what a newer writer added. Always prefix a
      // newline: that last write can leave a cut line even after this journal opened. The
      // separator keeps it from joining this entry, and later reads skip the cut line and empty
      // lines.
      appendFileSync(file, `\n${line}\n`);
      entries.push(entry);
    }
  };
  const latestEntry = (type: string, skip?: (data: unknown) => boolean) => {
    for (let i = entries.length - 1; i >= 0; i--) {
      const e = entries[i];
      if (e.kind === "note" && e.type === type && !skip?.(e.data)) return e.data;
    }
    return undefined;
  };
  const appendEntry = (type: string, data: unknown) => append({ kind: "note", type, data });
  return { entries, append, latestEntry, appendEntry };
}

function openSession(file: string, guard: () => void, tool: EchoTool): AgentSession {
  const { entries, append, latestEntry, appendEntry } = journal(file, guard);
  let busy = false;

  const talk = (): Entry[] => entries.filter((e) => e.kind !== "note");
  const lastPrompt = () => talk().filter((e): e is Prompt => e.kind === "prompt").at(-1);
  const lastResponse = () => talk().filter((e): e is Response => e.kind === "response").at(-1);
  // Results after the latest response only. Another response may reuse a call id.
  const results = () => {
    const all = talk();
    const response = lastResponse();
    const from = response ? all.lastIndexOf(response) : -1;
    const after = from < 0 ? [] : all.slice(from + 1);
    return after.filter((e): e is Result => e.kind === "result");
  };
  const answered = (callId: string) => results().some((r) => r.callId === callId);
  const unanswered = () =>
    (lastResponse()?.calls ?? []).filter((c) => !answered(c.id)).map((c) => c.id);
  const endsWithResponse = () => talk().at(-1)?.kind === "response";
  const open = (): ModelCall => {
    const response = lastResponse();
    const calls = response?.calls ?? [];
    return {
      toolCalls: calls.map(({ id, name }) => ({ id, name })),
      sequential: false,
      ended: response?.aborted === true,
    };
  };
  const settle = (callId: string, status: Outcome["status"], text: string) =>
    append({ kind: "result", callId, status, text });

  return {
    prepareStep() {
      if (busy) return "busy";
      // A stopped or crashed step's open calls become unknown, never run again. A whole-step
      // retry has no dispatch claim, so this is all that keeps it from running a tool twice.
      for (const id of unanswered()) settle(id, "unknown", "this call may or may not have run");
      const last = talk().at(-1);
      return last !== undefined && !(last.kind === "response" && last.calls.length === 0);
    },
    // The prompt id is the marker. `hasPrompt` must find what `recordPrompt` wrote.
    hasPrompt: (promptId) => entries.some((e) => e.kind === "prompt" && e.promptId === promptId),
    async recordPrompt(promptId, text) {
      // A prompt after an unanswered call is a transcript no provider would take.
      if (unanswered().length > 0) return false;
      append({ kind: "prompt", promptId, text });
      return true;
    },
    async modelCall(signal) {
      // A retry reuses the recorded response. The completion can be lost after the response
      // reached the file, and asking again would add a second response and a second charge.
      if (endsWithResponse()) return open();
      // A step already stopped asks the model nothing, and ends the run.
      if (signal?.aborted) {
        append({ kind: "response", text: "", calls: [], tokens: 0, aborted: true });
        return open();
      }
      // The deterministic model. The real one retries its provider here, inside the step, since
      // the Activity's retry policy assumes it does.
      const prompt = lastPrompt();
      if (!prompt) throw ApplicationFailure.nonRetryable("a model call with no prompt");
      // This prompt's result only. A turn that ended without a call-less response, such as a stop
      // mid-tool, leaves its result after the latest response, and it doesn't answer this prompt.
      const all = talk();
      const result = results()
        .filter((r) => all.lastIndexOf(r) > all.lastIndexOf(prompt))
        .at(-1);
      const text = !result
        ? ""
        : result.status === "ok"
          ? result.text
          : `the echo's outcome is ${result.status}: ${prompt.text}`;
      const calls = result ? [] : [{ id: `echo-${randomUUID()}`, name: "echo", text: prompt.text }];
      append({ kind: "response", text, calls, tokens: prompt.text.length + text.length });
      return open();
    },
    async runToolCall(callId, signal) {
      // Writes nothing. Calls may run in parallel, so only the seal records outcomes.
      if (answered(callId)) return undefined;
      const call = lastResponse()?.calls.find((c) => c.id === callId);
      if (!call) throw new Error(`the latest response has no call ${callId}`);
      busy = true;
      try {
        const text: unknown = await tool(call.text, signal);
        // A plain JS tool can resolve to anything, and the seal writes only text. A failed call
        // still lets the model answer, where an outcome the seal can't write fails the turn.
        const outcome: Outcome = typeof text === "string"
          ? { callId, status: "ok", text }
          : { callId, status: "failed", text: `the tool returned ${typeof text}, not text` };
        return outcome;
      } catch (err) {
        // A stopped or failed tool still reports what happened. Plain JSON, since the core keeps
        // it in a file until the seal reads it.
        const outcome: Outcome = { callId, status: "failed", text: String(err) };
        return outcome;
      } finally {
        busy = false;
      }
    },
    async sealStep(outcomes, { expectCalls, agentState }) {
      const asked = (lastResponse()?.calls ?? []).map((c) => c.id);
      // Results go only on the response the model call recorded, never on a later one.
      if (asked.join() !== expectCalls.join()) {
        throw ApplicationFailure.nonRetryable(
          `the seal expected calls [${expectCalls}], and the session has [${asked}]`,
        );
      }
      // Kept outcomes come back from a file. One that isn't an object goes to the append as it
      // is, which rejects it.
      const results = (outcomes as unknown[]).map((outcome) =>
        isObject(outcome)
          ? { kind: "result", callId: outcome.callId, status: outcome.status, text: outcome.text }
          : outcome,
      ) as Result[];
      // A retried seal skips what it already wrote, and so decides the same thing. The rest are
      // one append, which writes none of them unless every one is an entry. The seal must write a
      // step's results together.
      append(...results.filter((r) => !isObject(r) || !answered(r.callId)));
      // No retry and no compaction here, so `postRun` changes nothing. The turn is over once the
      // latest response asked for no tool.
      return { done: asked.length === 0, ...(agentState ? { agentState } : {}) };
    },
    waitForIdle: async () => {},
    dispose: () => {},
    answered,
    asked: (callId) => (lastResponse()?.calls ?? []).some((c) => c.id === callId),
    unanswered,
    endsWithResponse,
    lastAnswer: () => lastResponse()?.text ?? "",
    spend: () => ({
      tokens: entries.reduce((sum, e) => sum + (e.kind === "response" ? e.tokens : 0), 0),
    }),
    latestEntry,
    appendEntry,
  };
}

export function echoAgent(options: EchoOptions = {}): Agent {
  const tool = options.tool ?? (async (text: string) => text);
  return {
    async open(sessionFile, guard) {
      // Claims, kept results and fence tokens go in `${sessionFile}.*`, so the directory must be
      // writable too.
      mkdirSync(dirname(sessionFile), { recursive: true });
      return openSession(sessionFile, guard, tool);
    },
    async openRecord(sessionFile, guard) {
      if (!existsSync(sessionFile)) return undefined;
      const { latestEntry, appendEntry } = journal(sessionFile, guard);
      return { latestEntry, appendEntry };
    },
    unknownOutcome: (call: ToolCallRef): Outcome => ({
      callId: call.id,
      status: "unknown",
      text: "this call may have run, and its result was lost",
    }),
    notRunOutcome: (call: ToolCallRef): Outcome => ({
      callId: call.id,
      status: "not-run",
      text: "this call did not run: the turn stopped before it started",
    }),
  };
}

// An adapter keeps the agent's session format out of the Temporal core. Pi's adapter lives in
// `src/pi/agent.ts`.
//
// The agent owns the conversation in a session file. The Workflow holds only control state,
// so a turn can move to any Worker that can open that file.

import type { AgentState, Spend } from "./protocol.js";

export type { AgentState };

/** A tool call as the model asked for it. Only these two fields go into Workflow history. */
export interface ToolCallRef {
  readonly id: string;
  readonly name: string;
}

/**
 * What one tool call produced, in the agent's own shape. Kept beside the session file between
 * the tool call and the seal, so it must survive `JSON.stringify`. The core never looks inside.
 */
export type ToolOutcome = unknown;

export interface ModelCall {
  readonly toolCalls: readonly ToolCallRef[];
  // A tool of this step must run alone, after the ones before it.
  readonly sequential: boolean;
  // The response ended the turn's run. Nothing is dispatched, but the step is still sealed.
  readonly ended: boolean;
}

export interface Sealed {
  // The turn is over.
  readonly done: boolean;
  readonly agentState?: AgentState;
}

/**
 * One open session. Every append it makes must call the guard it was opened with first, and stop
 * if the guard throws. That's how a superseded attempt is kept out of the file.
 */
export interface AgentSession {
  /**
   * Settle what a stopped turn left open, before new work. True when the session has work to do,
   * false when the last turn is already answered, and `"busy"` when something else drives it.
   */
  prepareStep(): boolean | "busy";
  /** Whether a prompt with this id is already in the session. */
  hasPrompt(promptId: string): boolean;
  /** Put the prompt in the session without running the model. False when it wasn't recorded. */
  recordPrompt(promptId: string, text: string): Promise<boolean>;
  /** One model call. It records the response and the tool calls it asks for, and runs none. */
  modelCall(signal?: AbortSignal): Promise<ModelCall>;
  /**
   * Run one tool call the latest response recorded. It reports the outcome and writes nothing.
   * Undefined when the session already holds a result for the call. Stops like a user stop when
   * `signal` aborts.
   */
  runToolCall(callId: string, signal?: AbortSignal): Promise<ToolOutcome | undefined>;
  /**
   * Record a step's outcomes, in the order the model asked for the calls, and decide whether the
   * turn goes on. `postRun` false records only: no retry, no compaction, as for a stopped turn.
   * Stops its retry or compaction like a user stop when `signal` aborts.
   */
  sealStep(
    outcomes: readonly ToolOutcome[],
    options: {
      readonly expectCalls: readonly string[];
      readonly agentState?: AgentState;
      readonly postRun: boolean;
      readonly signal?: AbortSignal;
    },
  ): Promise<Sealed>;
  /** Wait for work the session started on its own after a seal, such as a compaction. */
  waitForIdle(): Promise<void>;
  dispose(): void;

  /** Whether the latest response's call `callId` already has a result in the session. */
  answered(callId: string): boolean;
  /** Whether the latest response asked for `callId`. An older response can reuse the id. */
  asked(callId: string): boolean;
  /** Calls in the session that have no result yet. */
  unanswered(): readonly string[];
  /** Whether the latest entry in the session is a model response. */
  endsWithResponse(): boolean;
  /** The text of the latest model response, or empty. */
  lastAnswer(): string;
  /** The session's total spend so far, compacted history included. Undefined when unknown. */
  spend(): Spend | undefined;
  /** The latest entry of this type, skipping the ones `skip` matches. For bookkeeping only. */
  latestEntry(type: string, skip?: (data: unknown) => boolean): unknown;
  /** Append a bookkeeping entry. It goes through the guard like any other append. */
  appendEntry(type: string, data: unknown): void;
}

export interface Agent {
  /** Open the session at `sessionFile`, creating it when it's new. */
  open(sessionFile: string, guard: () => void): Promise<AgentSession>;
  /**
   * The session's record alone, for a bookkeeping entry, without the model. Undefined when the
   * session holds nothing yet.
   */
  openRecord(
    sessionFile: string,
    guard: () => void,
  ): Promise<Pick<AgentSession, "latestEntry" | "appendEntry"> | undefined>;
  /** The outcome for a call that may have run, with no result kept. */
  unknownOutcome(call: ToolCallRef): ToolOutcome;
  /** The outcome for a call nothing started. Unknown would tell the model it may have run. */
  notRunOutcome(call: ToolCallRef): ToolOutcome;
}

/**
 * Where tools write, when that has to travel between hosts. Optional. Without one, every Worker
 * must see the same project directory. `src/tree/store.ts` ships it as git bundles.
 */
export interface ProjectStore {
  /** Make this host's copy current before work runs here. A refusal sends the work elsewhere. */
  ensure(sessionFile: string, writer?: Writer): Promise<void>;
  /** Publish this host's copy after work changed it. */
  capture(sessionFile: string, of?: { current?: Writer; fence?: StepRef }): Promise<void>;
  /** Keep work that can't be published where an operator can find it. */
  setAside(sessionFile: string): Promise<void>;
  /** Mark a tool call as writing here, until `endWrite`. */
  beginWrite(writer: Writer): Promise<void>;
  endWrite(writer: Writer): Promise<void>;
  /** Refuse anything a step closed without its host publishes later. */
  closeStep(sessionFile: string, step: StepRef): Promise<void>;
  /** Hand this host's copy back once the session goes idle. True when it was freed. */
  retire(sessionFile: string): Promise<boolean>;
  /** Copy a template's project into a new session. True when it copied. */
  adopt(template: string, sessionFile: string): Promise<boolean>;
  /** Whether `err` is this host saying no, which another host may answer differently. */
  isRefusal(err: unknown): boolean;
  /** Whether `err` refuses this host for good, until an operator clears it. */
  isQuarantine(err: unknown): boolean;
}

/** A tool call, for telling one step's writers from another's. */
export interface Writer {
  readonly turn: string;
  readonly step: number;
  readonly callId: string;
}

export interface StepRef {
  readonly turn: string;
  readonly step: number;
}

// OpenTelemetry tracing, off unless `PI_TEMPORAL_TRACING=1`. A trace follows a prompt from the
// client through the session Workflow to each model call and tool call, so an operator can see
// where a slow or failed turn spent its time. Spans go to an OTLP endpoint that the standard
// `OTEL_EXPORTER_OTLP_*` variables name, and `OTEL_SERVICE_NAME` names the process.
//
// Not for Workflow code. Workflows get their spans from the interceptor module below, which runs
// in the sandbox and hands finished spans to the Worker through a sink.

import { createRequire } from "node:module";
import { AsyncLocalStorageContextManager } from "@opentelemetry/context-async-hooks";
import {
  CompositePropagator,
  W3CBaggagePropagator,
  W3CTraceContextPropagator,
} from "@opentelemetry/core";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { Resource } from "@opentelemetry/resources";
import {
  BasicTracerProvider,
  BatchSpanProcessor,
  NoopSpanProcessor,
  type SpanProcessor,
} from "@opentelemetry/sdk-trace-base";
import {
  makeWorkflowExporter,
  OpenTelemetryActivityInboundInterceptor,
  OpenTelemetryActivityOutboundInterceptor,
  OpenTelemetryWorkflowClientInterceptor,
} from "@temporalio/interceptors-opentelemetry";
import type { WorkerOptions } from "@temporalio/worker";

/** The Workflow interceptors, for `workflowInterceptorModules` when the bundle is built. */
export const WORKFLOW_TRACING_MODULE = createRequire(import.meta.url).resolve(
  "@temporalio/interceptors-opentelemetry/lib/workflow-interceptors",
);

export interface Tracing {
  readonly spanProcessor: SpanProcessor;
  readonly resource: Resource;
  // Sends what's buffered. Call it before the process exits, or the last spans are lost.
  readonly shutdown: () => Promise<void>;
}

let started: Tracing | undefined;

/**
 * Registers a provider for this process. The trace context follows async calls, and it crosses
 * process boundaries only in the W3C headers. The Node provider would also read Jaeger and B3
 * headers when `OTEL_PROPAGATORS` asks, and its Jaeger reader can crash on a malformed one.
 */
export function registerTracing(resource: Resource, spanProcessor: SpanProcessor) {
  // In the constructor. `addSpanProcessor` is deprecated from 1.30 on and gone in 2.x.
  const provider = new BasicTracerProvider({ resource, spanProcessors: [spanProcessor] });
  provider.register({
    contextManager: new AsyncLocalStorageContextManager().enable(),
    propagator: new CompositePropagator({
      propagators: [new W3CTraceContextPropagator(), new W3CBaggagePropagator()],
    }),
  });
  return provider;
}

/**
 * Starts tracing for this process, once. The tracer provider is global, so Activity and client
 * spans reach the same exporter as the Workflow spans the sink delivers. A process that ends on
 * its own flushes on the way out. One that calls `process.exit` calls `flushTracing` first.
 */
export function startTracing(serviceName: string): Tracing {
  if (started) return started;
  const resource = new Resource({
    "service.name": process.env.OTEL_SERVICE_NAME ?? serviceName,
  });
  const spanProcessor = new BatchSpanProcessor(new OTLPTraceExporter());
  const provider = registerTracing(resource, spanProcessor);
  process.once("beforeExit", () => void provider.shutdown());
  started = { spanProcessor, resource, shutdown: () => provider.shutdown() };
  return started;
}

// Long enough for a batch to reach a collector nearby. A collector that's down mustn't hold the
// exit, so a failed process still ends.
const FLUSH_MS = 5_000;

/**
 * Sends the spans still buffered, if this process traces. `beforeExit` doesn't fire for
 * `process.exit`, so a process that exits on an error calls this first, or it loses the spans
 * that show the error.
 */
export async function flushTracing(): Promise<void> {
  if (!started) return;
  await Promise.race([
    started.shutdown().catch(() => undefined),
    new Promise((resolve) => setTimeout(resolve, FLUSH_MS).unref()),
  ]);
}

/** Client interceptors that start a trace for each call and pass it on in the call's headers. */
export const clientTracing = () => ({ workflow: [new OpenTelemetryWorkflowClientInterceptor()] });

/**
 * Worker options for tracing. The `exporter` sink is always there, because the prebuilt bundle
 * has the Workflow interceptors and calls it whether or not this process traces. Without tracing
 * it drops what it gets, so one image serves both.
 */
export function workerTracing(
  tracing: Tracing | undefined,
  bundled: boolean,
): Pick<WorkerOptions, "interceptors" | "sinks"> {
  const sinks = {
    exporter: tracing
      ? makeWorkflowExporter(tracing.spanProcessor, tracing.resource)
      : makeWorkflowExporter(new NoopSpanProcessor(), new Resource({})),
  };
  if (!tracing) return { sinks };
  return {
    sinks,
    interceptors: {
      activity: [
        (ctx) => ({
          inbound: new OpenTelemetryActivityInboundInterceptor(ctx),
          outbound: new OpenTelemetryActivityOutboundInterceptor(ctx),
        }),
      ],
      // A prebuilt bundle already has them. `scripts/bundle.mts` always puts them in.
      ...(bundled ? {} : { workflowModules: [WORKFLOW_TRACING_MODULE] }),
    },
  };
}

// Checks OpenTelemetry tracing. One trace must follow a prompt from the client call that sent it,
// through the session Workflow, to the Activity that ran its step. Also checks that a Worker with
// tracing off still runs a bundle that has the Workflow interceptors, as the prebuilt one does.
//
// Spans go to an in-memory exporter here. In production `startTracing` sends them over OTLP.
//
// Needs a Temporal server, no model key. Usage: npx tsx checks/tracing-check.mts

import { randomUUID } from "node:crypto";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { Client, Connection } from "@temporalio/client";
import { Resource } from "@opentelemetry/resources";
import { InMemorySpanExporter, SimpleSpanProcessor } from "@opentelemetry/sdk-trace-base";
import { bundleWorkflowCode } from "@temporalio/worker";
import { createSessionWorker } from "../src/core/session-worker.js";
import {
  clientTracing,
  registerTracing,
  WORKFLOW_TRACING_MODULE,
  type Tracing,
} from "../src/core/tracing.js";
import { UPDATES, workflowId } from "../src/core/protocol.js";
import type { Quiet, RunStepInput, RunStepResult, SessionInput } from "../src/core/protocol.js";

const address = process.env.TEMPORAL_ADDRESS ?? "127.0.0.1:7233";
const namespace = "default";
const failures: string[] = [];
const check = (what: string, ok: boolean, detail?: unknown) => {
  console.log(`${ok ? "PASS" : "FAIL"} ${what}${ok ? "" : ` (${JSON.stringify(detail)})`}`);
  if (!ok) failures.push(what);
};

const exporter = new InMemorySpanExporter();
const spanProcessor = new SimpleSpanProcessor(exporter);
const resource = new Resource({ "service.name": "tracing-check" });
const provider = registerTracing(resource, spanProcessor);
const tracing: Tracing = { spanProcessor, resource, shutdown: () => provider.shutdown() };

const activities = () => ({
  async runStep(input: RunStepInput): Promise<RunStepResult> {
    return { done: true, finalText: `answered ${input.promptId}` };
  },
  async retireSession() {},
  async adoptProject() {},
});

/** Runs one prompt through a session on a fresh Worker, and returns when it's answered. */
async function oneTurn(
  label: string,
  workerTracing: Tracing | undefined,
  workflowBundlePath?: string,
) {
  const taskQueue = `pi-tracing-${label}-${randomUUID().slice(0, 8)}`;
  const worker = await createSessionWorker({
    address,
    namespace,
    taskQueue,
    activities,
    tracing: workerTracing,
    workflowBundlePath,
  });
  const running = worker.run();
  const connection = await Connection.connect({ address });
  const client = new Client({ connection, namespace, interceptors: clientTracing() });
  try {
    const sessionId = `tracing-${label}-${randomUUID().slice(0, 8)}`;
    const input: SessionInput = { sessionId, sessionFile: `/unused/${sessionId}.jsonl` };
    const handle = await client.workflow.signalWithStart("piSession", {
      taskQueue,
      workflowId: workflowId(sessionId),
      args: [input],
      signal: "submitPrompt",
      signalArgs: [{ promptId: "one", text: "one" }],
    });
    const quiet = await handle.executeUpdate<Quiet, []>(UPDATES.waitForQuiet);
    await handle.terminate("tracing-check done");
    return quiet.finished?.outcome;
  } finally {
    await worker.stop();
    await running.catch(() => undefined);
    await connection.close();
  }
}

const root = await mkdtemp(join(tmpdir(), "pi-tracing-"));
try {
  const outcome = await oneTurn("on", tracing);
  check("a traced session answers", outcome === "answered", outcome);
  await spanProcessor.forceFlush();
  const spans = exporter.getFinishedSpans();
  const named = (prefix: string) => spans.filter((span) => span.name.startsWith(prefix));
  const started = named("SignalWithStartWorkflow");
  // From inside the Workflow. The run's own span ends only when the run does.
  const workflow = named("StartActivity:runStep");
  const step = named("RunActivity:runStep");
  check(
    "the client, the Workflow and the step each have a span",
    [started, workflow, step].every((found) => found.length > 0),
    spans.map((span) => span.name),
  );
  const traceId = started[0]?.spanContext().traceId;
  check(
    "and all three are in the trace the client started",
    traceId !== undefined &&
      workflow.some((span) => span.spanContext().traceId === traceId) &&
      step.some((span) => span.spanContext().traceId === traceId),
    { traceId, workflow: workflow.map((s) => s.spanContext().traceId) },
  );

  // The prebuilt bundle always has the Workflow interceptors. Untraced, its sink drops them.
  const bundle = join(root, "workflow-bundle.js");
  const { code } = await bundleWorkflowCode({
    workflowsPath: fileURLToPath(new URL("../src/workflow-bundle.ts", import.meta.url)),
    workflowInterceptorModules: [WORKFLOW_TRACING_MODULE],
  });
  await writeFile(bundle, code);
  const before = exporter.getFinishedSpans().length;
  const untraced = await oneTurn("off", undefined, bundle);
  check("an untraced Worker runs the prebuilt bundle", untraced === "answered", untraced);
  await spanProcessor.forceFlush();
  const workflowSpans = exporter
    .getFinishedSpans()
    .slice(before)
    .filter((span) => span.name.startsWith("StartActivity"));
  check("and exports none of its Workflow spans", workflowSpans.length === 0, workflowSpans.length);
} finally {
  await provider.shutdown();
  await rm(root, { recursive: true, force: true });
}

const bad = failures.length;
console.log(bad === 0 ? "tracing-check: OK" : `tracing-check: ${bad} failed`);
process.exit(bad === 0 ? 0 : 1);
